<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Holder\DcrInitialAccessTokenDescriptionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenDescriptionAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class DcrInitialAccessTokenDescriptionAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getDescription returns null on a freshly created holder.
     */
    public function testDescriptionNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenDescriptionAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDescriptionAssigned());
        $this->assertNull($holder->getDescription());
    }
}
class ImplWithDcrInitialAccessTokenDescriptionAttributeHolderUnitTest
{
    use DcrInitialAccessTokenDescriptionAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDescriptionRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDescription();
    }
}
